import com.google.android.gms.tasks.Tasks;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.text.*;import com.google.mlkit.vision.text.korean.KoreanTextRecognizerOptions;import com.google.mlkit.vision.label.*;import com.google.mlkit.vision.label.defaults.ImageLabelerOptions;
final class ScanEngine {
 static final class Item {
  Uri uri; String name,mime,path,parent="",hash="",reason="",labels="",text="",signature=""; long size,modified,duration; int width,height,score; boolean media,valid,checked,protectedFile,ocrOk; long visual; long[] frames; double sharp,light; int[] colors;
  String key(){return uri.toString();} boolean image(){return mime.startsWith("image/");} boolean video(){return mime.startsWith("video/");} String ext(){int i=name.lastIndexOf('.');return i<0?"":name.substring(i+1).toLowerCase(Locale.ROOT);} String desc(){return MainActivity.bytes(size)+(width>0?" · "+width+"×"+height:"")+(duration>0?" · "+duration/1000+"초":"");}
 }
 static final class Group {String title,reason; ArrayList<Item> items=new ArrayList<>(); Item best; Group(String t,String r){title=t;reason=r;}}
 static final class Result {ArrayList<Item> items=new ArrayList<>();ArrayList<Group> exact=new ArrayList<>(),similar=new ArrayList<>();int errors;boolean partial;long candidates(){return items.stream().filter(x->!x.protectedFile&&x.media&&x.score>=70).mapToLong(x->x.size).sum();}}
 interface Progress {void update(String s);}
 final Context c; final ContentResolver cr; final Set<String> protectedKeys; final Set<String> protectedPaths; final int threshold; final int mode; final boolean deep; final ScanPolicy policy; final Progress progress; final android.content.SharedPreferences prefs; final android.database.sqlite.SQLiteDatabase cache;
 ScanEngine(Context c,Set<String> p,Set<String> paths,int threshold,int mode,Progress cb){this.c=c;cr=c.getContentResolver();protectedKeys=p;protectedPaths=paths;this.threshold=threshold;this.mode=mode;this.deep=mode==2;this.policy=ScanPolicy.load(c);progress=cb;prefs=c.getSharedPreferences("cleaner",0);cache=c.openOrCreateDatabase("analysis.db",0,null);cache.execSQL("CREATE TABLE IF NOT EXISTS features (k TEXT PRIMARY KEY, stamp TEXT, value TEXT)");cache.execSQL("CREATE TABLE IF NOT EXISTS hashes (k TEXT PRIMARY KEY, stamp TEXT, value TEXT)");}
 Result run(Set<String> trees) {Result r=new Result();try {
  query(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,r,true);query(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,r,true);query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,r,true);
  HashSet<String> seen=new HashSet<>();for(Item i:r.items)seen.add(i.key());for(String t:trees){try{Uri u=Uri.parse(t);walk(u,DocumentsContract.getTreeDocumentId(u),"",seen,r,new HashSet<>());}catch(Exception e){r.errors++;}}
  TextRecognizer ocr=mode>0?TextRecognition.getClient(new KoreanTextRecognizerOptions.Builder().build()):null;
  ImageLabeler labeler=mode>0?ImageLabeling.getClient(ImageLabelerOptions.DEFAULT_OPTIONS):null;
  ExecutorService pool=Executors.newFixedThreadPool(mode==1?policy.workers:1);
  try{
   int total=r.items.size();progress.update("파일 "+total+"개 발견 · "+(mode==0?"빠른":mode==1?"스마트":"정밀")+" 분석");
   for(int start=0;start<total;start+=64){
    if(Thread.currentThread().isInterrupted()){r.partial=true;return r;}
    int end=Math.min(total,start+64);ArrayList<Item> fresh=new ArrayList<>();ArrayList<Future<?>> jobs=new ArrayList<>();
    for(int j=start;j<end;j++){Item i=r.items.get(j);protect(i);
     if(mode==0){if(isScreenshot(i))i.protectedFile=true;continue;}
     if(!readCache(i)){fresh.add(i);jobs.add(pool.submit(()->{try{analyze(i,null,null);}catch(Exception ignored){i.valid=false;}}));}
    }
    try{for(Future<?> job:jobs)job.get();}catch(InterruptedException e){Thread.currentThread().interrupt();r.partial=true;return r;}catch(ExecutionException e){r.errors++;}
    // ML Kit is deliberately serialized; only candidate images and screenshots are analyzed in smart mode.
    cache.beginTransaction();
    try{for(Item i:fresh){if(Thread.currentThread().isInterrupted()){r.partial=true;return r;}
     if(i.valid&&i.image()&&(deep||i.light<9||i.sharp<2.8||isScreenshot(i))){
      try{enrich(i,ocr,labeler);}catch(Exception e){r.errors++;if(isScreenshot(i))i.protectedFile=true;}
     }
     if(i.valid)writeCache(i);else if(i.image()||i.video())r.errors++;
    }cache.setTransactionSuccessful();}finally{cache.endTransaction();}
    for(int j=start;j<end;j++){Item i=r.items.get(j);if(isScreenshot(i)&&!i.ocrOk)i.protectedFile=true;score(i);}
    progress.update("내용 분석 "+end+" / "+total);
   }
  }finally{pool.shutdownNow();if(ocr!=null)ocr.close();if(labeler!=null)labeler.close();}
  progress.update("완전 중복 해시 검사");exact(r);if(r.partial)return r;if(mode>0){progress.update("유사 파일 그룹화");similar(r);}return r;
 }finally{cache.close();}}
 void query(Uri base,Result r,boolean media){
  boolean visual=base.equals(MediaStore.Images.Media.EXTERNAL_CONTENT_URI)||base.equals(MediaStore.Video.Media.EXTERNAL_CONTENT_URI);String[] cols=visual?new String[]{"_id","_display_name","mime_type","_size","date_modified","relative_path","is_favorite","width","height"}:new String[]{"_id","_display_name","mime_type","_size","date_modified","relative_path","is_favorite"};
  try(Cursor q=cr.query(base,cols,null,null,null)){if(q==null){r.errors++;return;}while(q.moveToNext()){Item i=new Item();i.uri=ContentUris.withAppendedId(base,q.getLong(0));i.name=n(q.getString(1));i.mime=n(q.getString(2));i.size=q.getLong(3);i.modified=q.getLong(4)*1000;i.path=n(q.getString(5));i.media=media;i.protectedFile=q.getInt(6)==1;if(visual){i.width=q.getInt(7);i.height=q.getInt(8);}r.items.add(i);}}catch(Exception e){r.errors++;}
 }
 void walk(Uri tree,String doc,String path,Set<String> seen,Result r,Set<String> visited){if(!visited.add(doc)||Thread.currentThread().isInterrupted())return;Uri kids=DocumentsContract.buildChildDocumentsUriUsingTree(tree,doc);String[] p={"document_id","_display_name","mime_type","_size","last_modified"};try(Cursor q=cr.query(kids,p,null,null,null)){if(q==null){r.errors++;return;}while(q.moveToNext()){String id=q.getString(0),name=n(q.getString(1)),mime=n(q.getString(2));if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)){walk(tree,id,path+name+"/",seen,r,visited);continue;}
 if(mime.startsWith("image/")||mime.startsWith("video/")||mime.startsWith("audio/"))continue;Item i=new Item();i.uri=DocumentsContract.buildDocumentUriUsingTree(tree,id);i.name=name;i.mime=mime;i.size=q.getLong(3);i.modified=q.getLong(4);i.path=path;i.parent=DocumentsContract.buildDocumentUriUsingTree(tree,doc).toString();i.media=false;if(seen.add(i.key()))r.items.add(i);}}catch(Exception e){r.errors++;}}
 void protect(Item i){String p=(i.path+"/"+i.name).toLowerCase(Locale.ROOT);i.protectedFile|=protectedKeys.contains(i.key())||p.matches(".*(업무|촬영|원본|project|footage|대본|backup|백업).*")||i.ext().matches("prproj|aep|drp|psd|docx|hwp|hwpx|xlsx|pptx|pdf");for(String x:protectedPaths)if(!x.isEmpty()&&p.contains(x.toLowerCase(Locale.ROOT)))i.protectedFile=true;}
 static String n(String x){return x==null?"":x;}
 boolean readCache(Item i){if(i.modified<=0)return false;try(Cursor q=cache.rawQuery("SELECT value FROM features WHERE k=? AND stamp=?",new String[]{i.key(),stamp(i)})){if(!q.moveToFirst())return false;org.json.JSONObject o=new org.json.JSONObject(q.getString(0));i.valid=o.getBoolean("v");i.ocrOk=o.optBoolean("ocrOk");i.visual=o.getLong("h");i.sharp=o.getDouble("s");i.light=o.getDouble("l");i.labels=o.optString("labels");i.text=o.optString("text");i.signature=o.optString("sig");i.width=o.optInt("w");i.height=o.optInt("height");i.duration=o.optLong("dur");org.json.JSONArray a=o.optJSONArray("frames");if(a!=null){i.frames=new long[a.length()];for(int j=0;j<a.length();j++)i.frames[j]=a.getLong(j);}a=o.optJSONArray("colors");if(a!=null){i.colors=new int[a.length()];for(int j=0;j<a.length();j++)i.colors[j]=a.getInt(j);}return true;}catch(Exception e){return false;}}
 String stamp(Item i){return "5:"+mode+":"+policy.thumbnail+":"+i.modified+":"+i.size;}
 void writeCache(Item i){if(i.modified<=0)return;try{org.json.JSONObject o=new org.json.JSONObject();o.put("v",i.valid);o.put("ocrOk",i.ocrOk);o.put("h",i.visual);o.put("s",i.sharp);o.put("l",i.light);o.put("labels",i.labels);o.put("text",i.text);o.put("sig",i.signature);o.put("w",i.width);o.put("height",i.height);o.put("dur",i.duration);if(i.frames!=null){org.json.JSONArray a=new org.json.JSONArray();for(long h:i.frames)a.put(h);o.put("frames",a);}if(i.colors!=null){org.json.JSONArray a=new org.json.JSONArray();for(int h:i.colors)a.put(h);o.put("colors",a);}android.content.ContentValues v=new android.content.ContentValues();v.put("k",i.key());v.put("stamp",stamp(i));v.put("value",o.toString());cache.insertWithOnConflict("features",null,v,android.database.sqlite.SQLiteDatabase.CONFLICT_REPLACE);}catch(Exception ignored){}}
 void enrich(Item i,TextRecognizer ocr,ImageLabeler labeler)throws Exception{
  Bitmap b=cr.loadThumbnail(i.uri,new Size(512,512),null);
  try{
   if(ocr!=null&&isScreenshot(i)){try{i.text=Tasks.await(ocr.process(InputImage.fromBitmap(b,0)),15,TimeUnit.SECONDS).getText();if(i.text.length()>5000)i.text=i.text.substring(0,5000);i.ocrOk=true;}catch(Exception ignored){i.ocrOk=false;}}
   if(labeler!=null&&(deep||i.light<9||i.sharp<2.8)){try{StringBuilder l=new StringBuilder();for(ImageLabel a:Tasks.await(labeler.process(InputImage.fromBitmap(b,0)),15,TimeUnit.SECONDS))if(a.getConfidence()>=.65)l.append(a.getText()).append(' ');i.labels=l.toString();}catch(Exception ignored){}}
  }finally{b.recycle();}
 }
 void analyze(Item i,TextRecognizer ocr,ImageLabeler labeler)throws Exception{if(i.image()){int side=deep?512:policy.thumbnail;Bitmap b=cr.loadThumbnail(i.uri,new Size(side,side),null);try{if(i.width==0)i.width=b.getWidth();if(i.height==0)i.height=b.getHeight();features(i,b);i.valid=true;}finally{b.recycle();}}
 else if(i.video()){MediaMetadataRetriever m=new MediaMetadataRetriever();try{m.setDataSource(c,i.uri);i.duration=Long.parseLong(n(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)));i.width=parse(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH));i.height=parse(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));ArrayList<Long> hs=new ArrayList<>();double lum=0;int count=deep?5:3;for(int f=1;f<=count;f++){Bitmap b=m.getScaledFrameAtTime(i.duration*1000*f/(count+1),MediaMetadataRetriever.OPTION_CLOSEST_SYNC,160,160);if(b!=null){Item tmp=new Item();features(tmp,b);hs.add(tmp.visual);lum+=tmp.light;b.recycle();}}if(hs.size()==count){i.frames=new long[count];for(int j=0;j<count;j++)i.frames[j]=hs.get(j);i.light=lum/count;i.valid=true;}}finally{m.release();}}
 else if(i.ext().matches("zip|apk|docx|xlsx|pptx|hwpx")&&i.size>0&&i.size<=20_000_000L){File f=File.createTempFile("archive-",".zip",c.getCacheDir());try{try(InputStream in=cr.openInputStream(i.uri);OutputStream out=new FileOutputStream(f)){byte[] buf=new byte[65536];long total=0;int len;while((len=in.read(buf))!=-1){total+=len;if(total>20_000_000L)throw new IOException("archive limit");out.write(buf,0,len);}}try(ZipFile z=new ZipFile(f)){TreeSet<String> names=new TreeSet<>();Enumeration<? extends ZipEntry> en=z.entries();while(names.size()<512&&en.hasMoreElements()){ZipEntry e=en.nextElement();names.add(e.getName());}if(!names.isEmpty())i.signature=String.join("\n",names);i.valid=!names.isEmpty();}}finally{f.delete();}}
 else if(i.ext().matches("txt|csv|json|log|md|srt|vtt")&&i.size<=1_000_000){try(InputStream in=cr.openInputStream(i.uri)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while(out.size()<65536&&(n=in.read(b,0,Math.min(b.length,65536-out.size())))!=-1)out.write(b,0,n);i.text=new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);i.signature=i.text;i.valid=true;}}
 }
 static int parse(String s){try{return Integer.parseInt(s);}catch(Exception e){return 0;}}
 static boolean isScreenshot(Item i){String s=(i.path+i.name).toLowerCase(Locale.ROOT);return s.contains("screenshot")||s.contains("스크린샷")||s.contains("캡처");}
 static int gray(int p){return (Color.red(p)*30+Color.green(p)*59+Color.blue(p)*11)/100;}
 static void features(Item i,Bitmap b){Bitmap h=Bitmap.createScaledBitmap(b,9,8,true);long bits=0;for(int y=0;y<8;y++)for(int x=0;x<8;x++)if(gray(h.getPixel(x,y))>gray(h.getPixel(x+1,y)))bits|=1L<<(y*8+x);i.visual=bits;if(h!=b)h.recycle();Bitmap s=Bitmap.createScaledBitmap(b,64,64,true);double sum=0,lap=0;int[] colors=new int[12],pixels=new int[4096],grays=new int[4096];s.getPixels(pixels,0,64,0,0,64,64);for(int j=0;j<4096;j++)grays[j]=gray(pixels[j]);for(int y=1;y<63;y++)for(int x=1;x<63;x++){int j=y*64+x,p=pixels[j],v=grays[j];sum+=v;lap+=Math.abs(4*v-grays[j-1]-grays[j+1]-grays[j-64]-grays[j+64]);colors[Color.red(p)/64]++;colors[4+Color.green(p)/64]++;colors[8+Color.blue(p)/64]++;}i.light=sum/3844;i.sharp=lap/3844;i.colors=colors;if(s!=b)s.recycle();}
 void score(Item i){if(i.protectedFile)return;String low=(i.name+" "+i.text+" "+i.labels).toLowerCase(Locale.ROOT);if(low.matches("(?s).*(receipt|invoice|영수증|주문번호|계좌|결제|신분증|대본|계약|password|비밀번호).*")){i.protectedFile=true;i.reason="중요 텍스트 감지";return;}if(i.image()&&i.valid){if(i.light<9){i.score=75;i.reason="거의 검은 사진 · 직접 확인";}else if(i.sharp<2.8){i.score=55;i.reason="낮은 선명도 · 의도적 사진일 수 있음";}else if(isScreenshot(i)){i.score=35;i.reason="스크린샷";}}else if(i.video()&&i.valid&&i.light<9){i.score=72;i.reason="샘플 프레임이 어두움 · 음성 확인 필요";}else if(!i.media&&i.ext().matches("tmp|temp|log|bak|apk")){i.score=65;i.reason="임시/설치/로그 후보 · 보관 여부 확인";if(i.modified>0&&System.currentTimeMillis()-i.modified>30L*86400000)i.score=72;}if(prefs.getInt("keep:"+i.ext()+":"+isScreenshot(i),0)>2)i.score=Math.max(0,i.score-15);}
 String sha(Item i)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=cr.openInputStream(i.uri)){if(in==null)throw new IOException();byte[] b=new byte[262144];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedException();d.update(b,0,n);}}return java.util.Base64.getEncoder().encodeToString(d.digest());}
 String hashStamp(Item i){return "1:"+i.modified+":"+i.size;}
 String cachedHash(Item i)throws Exception{
  if(i.modified>0){try(Cursor q=cache.rawQuery("SELECT value FROM hashes WHERE k=? AND stamp=?",new String[]{i.key(),hashStamp(i)})){if(q.moveToFirst())return q.getString(0);}}
  String value=sha(i);if(i.modified>0){ContentValues v=new ContentValues();v.put("k",i.key());v.put("stamp",hashStamp(i));v.put("value",value);cache.insertWithOnConflict("hashes",null,v,android.database.sqlite.SQLiteDatabase.CONFLICT_REPLACE);}return value;
 }
 String prefix(Item i)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=cr.openInputStream(i.uri)){if(in==null)throw new IOException();byte[] b=new byte[8192];int left=policy.prefixBytes;while(left>0){if(Thread.currentThread().isInterrupted())throw new InterruptedException();int n=in.read(b,0,Math.min(left,b.length));if(n<0)break;d.update(b,0,n);left-=n;}}return java.util.Base64.getEncoder().encodeToString(d.digest());}
 void exact(Result r){
  Map<Long,List<Item>> sizes=new HashMap<>();for(Item i:r.items)if(i.size>0)sizes.computeIfAbsent(i.size,k->new ArrayList<>()).add(i);
  Map<String,Group> hashes=new HashMap<>();int done=0;
  for(List<Item> a:sizes.values())if(a.size()>1){
   if(Thread.currentThread().isInterrupted()){r.partial=true;return;}
   Map<String,List<Item>> candidates=new HashMap<>();
   for(Item i:a){try{candidates.computeIfAbsent(prefix(i),k->new ArrayList<>()).add(i);}catch(InterruptedException ex){Thread.currentThread().interrupt();r.partial=true;return;}catch(Exception ex){r.errors++;}}
   for(List<Item> bucket:candidates.values())if(bucket.size()>1)for(Item i:bucket){try{i.hash=cachedHash(i);hashes.computeIfAbsent(i.size+":"+i.hash,k->new Group("완전 중복","SHA-256 전체 내용 일치")).items.add(i);}catch(InterruptedException ex){Thread.currentThread().interrupt();r.partial=true;return;}catch(Exception ex){r.errors++;}}
   done+=a.size();if(done%128<a.size())progress.update("완전 중복 검증 "+done+"개");
  }
  for(Group group:hashes.values())if(group.items.size()>1){finish(group,true);r.exact.add(group);}
 }
 static double quality(Item i){return (i.protectedFile?1e12:0)+Math.log1p((double)i.width*i.height)*10+i.sharp-Math.abs(i.light-125)*.02+Math.log1p(i.size);}
 void finish(Group g,boolean exact){g.items.sort((a,b)->Double.compare(quality(b),quality(a)));g.best=g.items.get(0);for(Item i:g.items)if(i!=g.best&&!i.protectedFile){int s=exact?95:76;if(i.score<s){i.score=s;i.reason=exact?"내용 완전 중복 · 보관본 있음":"유사 파일 · 원본/편집본 직접 비교";}}}
 boolean close(Item a,Item b){if(!a.mime.equals(b.mime)&&!(a.image()&&b.image())&&!(a.video()&&b.video()))return false;if(a.image()&&b.image()&&a.valid&&b.valid&&a.colors!=null&&b.colors!=null){if(a.width<=0||b.width<=0||a.height<=0||b.height<=0)return false;double ratio=(a.width/(double)a.height)/(b.width/(double)b.height);if(ratio<.78||ratio>1.28)return false;int dist=Long.bitCount(a.visual^b.visual),col=0;for(int j=0;j<12;j++)col+=Math.abs(a.colors[j]-b.colors[j]);return dist<=threshold&&col<7200&&Math.abs(a.light-b.light)<40;}if(a.video()&&b.video()&&a.frames!=null&&b.frames!=null){if(Math.abs(a.duration-b.duration)>Math.max(1500,Math.min(a.duration,b.duration)*.05))return false;if(a.frames.length!=b.frames.length)return false;int d=0;for(int j=0;j<a.frames.length;j++)d+=Long.bitCount(a.frames[j]^b.frames[j]);return d<=a.frames.length*threshold;}if(!a.media&&!b.media&&!a.signature.isEmpty()&&!b.signature.isEmpty()&&a.ext().equals(b.ext())){Set<String>x=tokens(a.signature),y=tokens(b.signature);if(x.size()<3||y.size()<3)return false;int u=x.size();for(String s:y)if(!x.contains(s))u++;x.retainAll(y);return x.size()/(double)u>=.85;}return false;}
 static Set<String> tokens(String s){return new HashSet<>(Arrays.asList(s.toLowerCase(Locale.ROOT).split("[\\s,;]+")));}
 void similar(Result r){
 Map<String,List<Group>> idx=new HashMap<>();ArrayList<Group> groups=new ArrayList<>();for(Item i:r.items){if(Thread.currentThread().isInterrupted()){r.partial=true;return;}if(!(i.image()&&i.valid||i.video()&&i.frames!=null||!i.signature.isEmpty()))continue;ArrayList<String> keys=new ArrayList<>();if(i.image()||i.video()){long h=i.image()?i.visual:i.frames[i.frames.length/2];for(int j=0;j<8;j++)keys.add((i.image()?"p":"v")+j+":"+((h>>>(j*8))&255));}else keys.add("doc:"+i.ext());Set<Group> candidates=new LinkedHashSet<>();for(String key:keys)candidates.addAll(idx.getOrDefault(key,Collections.emptyList()));Group match=null;for(Group g:candidates){if(g.items.size()>=100)continue;boolean ok=true;for(Item m:g.items)if(!close(i,m)){ok=false;break;}if(ok){match=g;break;}}if(match==null){match=new Group(i.image()?"유사 사진":i.video()?"유사 영상":"유사 문서/압축 파일","시각 특징 또는 내용 유사 · 동일 파일 보장 아님");groups.add(match);}match.items.add(i);for(String key:keys){List<Group> a=idx.computeIfAbsent(key,k->new ArrayList<>());if(!a.contains(match)&&a.size()<400)a.add(match);}}for(Group g:groups)if(g.items.size()>1){finish(g,false);r.similar.add(g);}}
}
